style.css:
/* Hide YouTube’s default logo */
ytd-topbar-logo-renderer svg {
  display: none !important;
}

/* Apply the Dr. Eggman GIF as the YouTube logo */
ytd-topbar-logo-renderer {
  width: 56px !important;
  height: 56px !important;

  background-image: url("https://media.tenor.com/O7ini3P_9YUAAAAi/dr-eggman-doctor-eggman.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;

  image-rendering: pixelated;
}

/* Optional hover wiggle */
ytd-topbar-logo-renderer:hover {
  animation: eggmanWiggle 0.4s infinite alternate;
}

@keyframes eggmanWiggle {
  from { transform: translateX(0); }
  to   { transform: translateX(4px); }
}
